// Lazy getter to avoid duplicating 3MB of memory
Object.defineProperty(window.STATIC_DATA, 'questions', {
  configurable: true,
  enumerable: true,
  get: function() {
    if (!this._cachedQuestions) {
      this._cachedQuestions = [
        ...(this.lectureQuestions || []),
        ...(this.bankQuestions || []),
        ...(this.midtermQuestions || []),
        ...(this.modelQuestions || [])
      ];
    }
    return this._cachedQuestions;
  }
});

window.UQP_STATIC_DATA = window.STATIC_DATA;
